const currencyFormatter = new Intl.NumberFormat('en-US', {
  currency: 'USD',
  maximumFractionDigits: 2,
  minimumFractionDigits: 2,
  style: 'currency',
});

const compactCurrencyFormatter = new Intl.NumberFormat('en-US', {
  currency: 'USD',
  maximumFractionDigits: 0,
  minimumFractionDigits: 0,
  style: 'currency',
});

export function formatCurrency(value: number): string {
  return currencyFormatter.format(value);
}

export function formatCompactCurrency(value: number): string {
  return compactCurrencyFormatter.format(value);
}

export function formatHours(value: number): string {
  return new Intl.NumberFormat('en-US', {
    maximumFractionDigits: 2,
    minimumFractionDigits: 0,
  }).format(value);
}

export function formatPercent(value: number): string {
  return new Intl.NumberFormat('en-US', {
    maximumFractionDigits: 1,
    minimumFractionDigits: 0,
    style: 'percent',
  }).format(value / 100);
}

export type InvoiceParty = {
  name: string;
  address: string;
  email: string;
  phone: string;
};

export type InvoiceLineItem = {
  description: string;
  quantity: number;
  unitPrice: number;
};

export type InvoiceSummary = {
  subtotal: number;
  tax: number;
  total: number;
};

export type InvoicePaymentTerms = {
  dueDate: string;
  method: string;
  gst: string;
};

export type InvoiceBaseData = {
  invoiceNumber: string;
  invoiceDate: string;
  dueDate: string;
  companyName: string;
  subtitle: string;
  companyAddress: string;
  companyEmail: string;
  billTo: InvoiceParty;
  items: InvoiceLineItem[];
  summary: InvoiceSummary;
  paymentTerms: InvoicePaymentTerms;
  notes?: string | undefined;
};

export type ReportMetricTone = 'success' | 'warning' | 'destructive' | 'info';

export type ReportSummaryMetric = {
  label: string;
  value: string;
  trend?: string | undefined;
  tone?: ReportMetricTone | undefined;
};

export type ReportRow = {
  label: string;
  owner: string;
  status: string;
  progress: number;
  risk?: string | undefined;
  detail?: string | undefined;
  metric?: string | undefined;
  region?: string | undefined;
};

export type ReportSeriesPoint = {
  label: string;
  value: number;
};

export type BaseReportData = {
  title: string;
  subtitle: string;
  generatedAt: string;
  period: string;
  author: string;
  summary: ReportSummaryMetric[];
  rows: ReportRow[];
  series: ReportSeriesPoint[];
  highlights: string[];
};

export type {
  InvoiceBaseData,
  InvoiceLineItem,
  InvoiceParty,
  InvoicePaymentTerms,
  InvoiceSummary,
} from '@/components/pdf/blocks/shared/invoice.types';
export type {
  BaseReportData,
  ReportMetricTone,
  ReportRow,
  ReportSeriesPoint,
  ReportSummaryMetric,
} from '@/components/pdf/blocks/shared/report.types';
export { formatCompactCurrency, formatCurrency, formatHours, formatPercent } from '@/components/pdf/blocks/shared/format';
